+// Return the sequence of digits `num_str` with those digits grouped by group_size from the
+// right end and separated by group_separator.
+// e.g. _group_with_separator("1234567890", ",", 3) -> "1,234,567,890"
+String _group_with_separator(const String &p_num_str, const char32_t p_group_separator, const int p_group_size) {
+	StringBuffer grouped;
+	const int num_size = p_num_str.size();
+	// Track how much of num_str we've copied.
+	int cur_pos = (num_size - 2) % p_group_size + 1; // find location of first separator.
+	if (cur_pos > 0) {
+		grouped.append(p_num_str.substr(0, cur_pos));
+	}
+	while (cur_pos + 1 < num_size) {
+		grouped.append(p_group_separator);
+		grouped.append(p_num_str.substr(cur_pos, p_group_size));
+		cur_pos += p_group_size;
+	}
+	return grouped.as_string();
+}
